// Fuzzer stub for qrcodegen_encodeText
// - Generates a UTF-8-ish string without embedded NULs
// - Picks valid ECC, version range [1,40], and mask (-1 or 0..7)
// - Allocates non-overlapping tempBuffer and qrcode buffers sized to BUFFER_LEN_FOR_VERSION(maxVersion)
// - Calls the target; does not treat false as an error (data may not fit)
{
    // Produce a string with no embedded NULs to satisfy API requirement
    std::string raw = FUZZ_PARAM_STR();
    std::string textNoNul;
    textNoNul.reserve(raw.size());
    for (char c : raw) { if (c != '\0') textNoNul.push_back(c); }
    const char *text = textNoNul.c_str();

    // Version constraints: 1 <= minVersion <= maxVersion <= 40
    int minVersion = (int)(*FUZZ_PARAM(unsigned int) % 40) + 1; // 1..40
    int maxVersion = minVersion + (int)(*FUZZ_PARAM(unsigned int) % (41 - (unsigned int)minVersion)); // min..40

    // ECC level in [0..3]
    enum qrcodegen_Ecc ecl = (enum qrcodegen_Ecc)((unsigned)(*FUZZ_PARAM(unsigned int)) % 4u);

    // Mask selection: AUTO (-1) or 0..7
    unsigned mv = *FUZZ_PARAM(unsigned int) % 9u; // 0..8
    enum qrcodegen_Mask mask = (mv == 0u) ? qrcodegen_Mask_AUTO : (enum qrcodegen_Mask)((int)mv - 1);

    bool boostEcl = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;

    // Allocate non-overlapping buffers according to maxVersion
    int len = qrcodegen_BUFFER_LEN_FOR_VERSION(maxVersion);
    if (len <= 0) { FUZZ_BAIL(); }
    uint8_t *tempBuffer = new uint8_t[(size_t)len];
    uint8_t *qrcode = new uint8_t[(size_t)len];
    if (!tempBuffer || !qrcode) { FUZZ_BAIL(); }

    // Invoke target
    (void)qrcodegen_encodeText(text, tempBuffer, qrcode, ecl, minVersion, maxVersion, mask, boostEcl);

    // Cleanup
    delete[] tempBuffer;
    delete[] qrcode;

    // Validation: All API constraints enforced (versions, mask, non-overlapping buffers, text without NULs).
    // Normal false return is acceptable and not treated as error.
}

