// - Builds 1..3 valid segments using factory helpers with properly sized backing buffers
// - Allocates non-overlapping tempBuffer/qrcode sized to BUFFER_LEN_FOR_VERSION(VERSION_MAX)
// - Calls the target; does not treat false as an error
{
    // Decide number of segments 1..3
    size_t nSegs = (size_t)((*FUZZ_PARAM(unsigned int) % 3u) + 1u);

    // Storage for segments and their backing buffers
