    uint8_t *backingBufs[3] = {nullptr, nullptr, nullptr};

    // Build each segment inline (avoid lambdas to keep FUZZ_PARAM usage simple)
    for (size_t i = 0; i < nSegs; i++) {
        unsigned choiceSeed = *FUZZ_PARAM(unsigned int);
        unsigned choice = (choiceSeed + (unsigned)i) % 4u; // BYTE, NUM, ALNUM, or ECI

        if (choice == 0u) {
            // BYTE segment
            size_t n = (size_t)(*FUZZ_PARAM(unsigned int) % 512u);
            std::string data = FUZZ_PARAM_STR(); // length >= 1
            size_t need = qrcodegen_calcSegmentBufferSize(qrcodegen_Mode_BYTE, n);
            if (need == SIZE_MAX) { n = 0; need = qrcodegen_calcSegmentBufferSize(qrcodegen_Mode_BYTE, n); }
            backingBufs[i] = new uint8_t[need ? need : 1];
            if (!backingBufs[i]) { FUZZ_BAIL(); }
            std::vector<uint8_t> tmp(n);
            for (size_t k = 0; k < n; k++) tmp[k] = (uint8_t)data[k % data.size()];
            segs[i] = qrcodegen_makeBytes(tmp.data(), n, backingBufs[i]);
        } else if (choice == 1u) {
            // NUMERIC segment: generate digits-only text of length n
            size_t n = (size_t)(*FUZZ_PARAM(unsigned int) % 512u);
            unsigned seed = *FUZZ_PARAM(unsigned int);
            std::string digits; digits.reserve(n);
            for (size_t k = 0; k < n; k++) {
                unsigned v = (seed + (unsigned)k) % 10u;
                digits.push_back((char)('0' + (int)v));
            }
            size_t need = qrcodegen_calcSegmentBufferSize(qrcodegen_Mode_NUMERIC, n);
            if (need == SIZE_MAX) { n = 0; digits.clear(); size_t nn = qrcodegen_calcSegmentBufferSize(qrcodegen_Mode_NUMERIC, 0); need = (nn == SIZE_MAX) ? 0 : nn; }
            backingBufs[i] = new uint8_t[need ? need : 1];
            if (!backingBufs[i]) { FUZZ_BAIL(); }
            segs[i] = qrcodegen_makeNumeric(digits.c_str(), backingBufs[i]);
        } else if (choice == 2u) {
            // ALPHANUMERIC segment: generate allowed-character text of length n
            size_t n = (size_t)(*FUZZ_PARAM(unsigned int) % 512u);
            static const char table[] = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ $%*+-./:";
            const size_t T = sizeof(table) - 1;
            unsigned seed = *FUZZ_PARAM(unsigned int);
            std::string text; text.reserve(n);
            for (size_t k = 0; k < n; k++) {
                text.push_back(table[(seed + (unsigned)k) % T]);
            }
            size_t need = qrcodegen_calcSegmentBufferSize(qrcodegen_Mode_ALPHANUMERIC, n);
            if (need == SIZE_MAX) { n = 0; text.clear(); size_t nn = qrcodegen_calcSegmentBufferSize(qrcodegen_Mode_ALPHANUMERIC, 0); need = (nn == SIZE_MAX) ? 0 : nn; }
            backingBufs[i] = new uint8_t[need ? need : 1];
            if (!backingBufs[i]) { FUZZ_BAIL(); }
            segs[i] = qrcodegen_makeAlphanumeric(text.c_str(), backingBufs[i]);
        } else {
            // ECI segment
            long assignVal = (long)(*FUZZ_PARAM(unsigned int) % 1000000u); // plausible bounded range
            size_t need = qrcodegen_calcSegmentBufferSize(qrcodegen_Mode_ECI, 0);
            if (need == SIZE_MAX) { FUZZ_BAIL(); }
            backingBufs[i] = new uint8_t[need ? need : 1];
            if (!backingBufs[i]) { FUZZ_BAIL(); }
            segs[i] = qrcodegen_makeEci(assignVal, backingBufs[i]);
