    uint8_t *tempBuffer = new uint8_t[(size_t)bufLen];
    uint8_t *qrcode = new uint8_t[(size_t)bufLen];
    if (!tempBuffer || !qrcode) { FUZZ_BAIL(); }

    enum qrcodegen_Ecc ecl = (enum qrcodegen_Ecc)((unsigned)(*FUZZ_PARAM(unsigned int)) % 4u);

    // Invoke target (false is a valid outcome if data doesn't fit at requested ECC)
    (void)qrcodegen_encodeSegments(segs, nSegs, ecl, tempBuffer, qrcode);

    // Cleanup
    delete[] tempBuffer;
    delete[] qrcode;
    for (size_t i = 0; i < nSegs; i++) delete[] backingBufs[i];

    // Validation: Segment invariants enforced via factory helpers and buffer sizing; non-overlapping
    // temp/qrcode allocated to VERSION_MAX length. Normal false return is acceptable.
