import random
import string
from typing import List

# Generator for QR alphanumeric strings suitable for qrcodegen_makeAlphanumeric
# and general segment construction in the provided fuzz stubs. The fuzz harness
# will consume this as FUZZ_PARAM_STR and also modulo index into it for bytes.
# We aim to provide varied, valid inputs that trigger different encoder paths
# (numeric/alphanumeric/byte/ECI segments, multiple segment counts, sizes).

ALNUM_TABLE = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ $%*+-./:"

# Some interesting substrings to encourage diverse behavior
INTERESTING_TOKENS = [
    "0", "1", "9",            # single digits
    "A", "Z",                  # single letters
    " ", "$", "%", "*", "+", "-", ".", "/", ":",  # special allowed chars
    "HELLO", "WORLD", "QR", "CODE",
    "1234567890",              # numeric run
    "ABCDEFGHIJKLMNOPQRSTUVWXYZ",  # full alphabet
    "THE QUICK BROWN FOX JUMPS OVER 13 LAZY DOGS".upper().replace("13", "13"),
]

# Some patterns of differing character distributions
def make_pattern_numeric(n: int, rnd: random.Random) -> str:
    return ''.join(rnd.choice(string.digits) for _ in range(n))

def make_pattern_alpha(n: int, rnd: random.Random) -> str:
    letters = string.ascii_uppercase
    return ''.join(rnd.choice(letters) for _ in range(n))

def make_pattern_alnum(n: int, rnd: random.Random) -> str:
    return ''.join(rnd.choice(ALNUM_TABLE) for _ in range(n))

def make_pattern_repeated(token: str, n: int) -> str:
    if not token:
        return ''
    reps = max(1, n // len(token))
    s = (token * reps)[:n]
    return s

def mix_segments(parts: List[str]) -> str:
    return ''.join(parts)

def bounded_length(rnd: random.Random, lo: int, hi: int) -> int:
    # skew toward small sizes but allow occasional large sizes up to 4096
    assert lo <= hi
    r = rnd.random()
    if r < 0.60:
        return rnd.randint(lo, min(64, hi))
    elif r < 0.90:
        return rnd.randint(min(64, hi//2 if hi>=2 else hi), hi)
    else:
        return hi

def build_interesting_string(rnd: random.Random, max_len: int) -> str:
    # Decide number of mixed segments (1..3)
    nsegs = rnd.randint(1, 3)
    parts: List[str] = []

    # Reserve a total target length
    total_len = bounded_length(rnd, 0, max_len)
    remaining = total_len

    for i in range(nsegs):
        if i == nsegs - 1:
            seg_len = remaining
        else:
            seg_len = rnd.randint(0, remaining) if remaining > 0 else 0
        remaining -= seg_len

        choice = rnd.randrange(6)
        if choice == 0:
            parts.append(make_pattern_numeric(seg_len, rnd))
        elif choice == 1:
            parts.append(make_pattern_alpha(seg_len, rnd))
        elif choice == 2:
            parts.append(make_pattern_alnum(seg_len, rnd))
        elif choice == 3:
            token = rnd.choice(INTERESTING_TOKENS)
            parts.append(make_pattern_repeated(token, seg_len))
        elif choice == 4:
            # alternating digit and letter
            seq = []
            for k in range(seg_len):
                if k % 2 == 0:
                    seq.append(rnd.choice(string.digits))
                else:
                    seq.append(rnd.choice(string.ascii_uppercase))
            parts.append(''.join(seq))
        else:
            # rich special characters from allowed table
            specials = " $%*+-./:"
            pool = string.digits + string.ascii_uppercase + specials
            parts.append(''.join(rnd.choice(pool) for _ in range(seg_len)))

    s = mix_segments(parts)

    # Occasionally force boundary cases
    if rnd.random() < 0.1 and len(s) < max_len:
        # append a long numeric run to test numeric compression transition
        run_len = min(max_len - len(s), rnd.randint(10, 128))
        s += make_pattern_numeric(run_len, rnd)

    if rnd.random() < 0.1 and len(s) < max_len:
        # append repeated special chars
        token = rnd.choice([" ", "$", "%", "*", "+", "-", ".", "/", ":"])
        run_len = min(max_len - len(s), rnd.randint(5, 64))
        s += make_pattern_repeated(token, run_len)

    return s

# The fuzz stubs access FUZZ_PARAM_STR and also may mod-index this string for
# raw bytes in byte segments. Any byte value is accepted in BYTE mode; we
# restrict to ASCII here but ensure good variety. The harness also sets
# segment lengths independently, so over-provide data to avoid tiny cycles.

MAX_OUT_BYTES = 4096

def generate(seed: int) -> bytes:
    rnd = random.Random(seed)

    # Decide a target overall size for the returned buffer (1..4096)
    target_size = bounded_length(rnd, 1, MAX_OUT_BYTES)

    # Build a backbone alphanumeric string that is valid per QR alphanumeric set
    s = build_interesting_string(rnd, target_size)

    # Ensure non-empty
    if not s:
        s = "A"

    # Trim or pad to target_size
    if len(s) < target_size:
        pad = build_interesting_string(rnd, target_size - len(s))
        s += pad
    elif len(s) > target_size:
        s = s[:target_size]

    # Return as bytes (ASCII-safe)
    return s.encode('ascii', errors='strict')
